package org.brightstats.stats;

import java.util.*;
import java.security.MessageDigest;
import java.nio.ByteBuffer;

/** Analyze each proper imputation and pool parameter inference; no pooled likelihood fit indices. */
public final class ImputedSem {
    private ImputedSem(){}
    public record Options(GaussianImputation.Options imputation,FimlSem.Options analysis,Double completeDegreesOfFreedom,boolean sandwichCovariance){public Options{Objects.requireNonNull(imputation);Objects.requireNonNull(analysis);if(completeDegreesOfFreedom!=null&&(!(completeDegreesOfFreedom>0)||!Double.isFinite(completeDegreesOfFreedom)))throw new IllegalArgumentException("Complete-data df must be positive and finite, or unspecified for large-sample inference.");}public static Options defaults(){return new Options(GaussianImputation.Options.defaults(),FimlSem.Options.defaults(),null,false);}}
    public record CompletedAnalysis(int index,String dataSha256,int iterations,boolean converged,boolean locallyIdentified){}
    public record Fit(SemModel.Model model,Options options,int suppliedRows,List<Integer> sourceRows,int missingCells,double maximumSplitRhat,double[][][] meanTraces,RubinPooling.Result pooled,List<CompletedAnalysis> analyses,List<String> warnings){public Fit{sourceRows=List.copyOf(sourceRows);meanTraces=Arrays.stream(meanTraces).map(Matrices::copy).toArray(double[][][]::new);analyses=List.copyOf(analyses);warnings=List.copyOf(warnings);}@Override public double[][][] meanTraces(){return Arrays.stream(meanTraces).map(Matrices::copy).toArray(double[][][]::new);}}
    public static Fit fit(double[][] source,SemModel.Model model,Options options,java.util.function.IntConsumer progress){
        if(model.parameters().size()>80)throw new IllegalArgumentException("The pooled SEM workflow supports at most 80 free parameters.");if(source.length==0||source[0].length!=model.observed().length)throw new IllegalArgumentException("Imputation columns must follow the SEM observed order; auxiliary predictors require a separate declared imputation model.");
        var imputed=GaussianImputation.impute(source,options.imputation(),progress);List<RubinPooling.Estimate> estimates=new ArrayList<>();List<CompletedAnalysis> analyses=new ArrayList<>();List<String> labels=model.parameters().stream().map(SemModel.Parameter::name).toList();List<double[][]> completed=imputed.completed();List<String> warnings=new ArrayList<>(imputed.warnings());
        for(int i=0;i<completed.size();i++){Matrices.interrupted();var fit=FimlSem.fit(completed.get(i),model,options.analysis());if(!fit.converged()||!fit.locallyIdentified()||fit.boundary())throw new IllegalArgumentException("Imputation "+(i+1)+" did not produce a regular complete-data fit. No failed analyses were silently dropped or replaced; revise the model or investigate the imputation diagnostics.");estimates.add(new RubinPooling.Estimate(labels,fit.estimates(),options.sandwichCovariance()?fit.sandwichCovariance():fit.parameterCovariance()));analyses.add(new CompletedAnalysis(i+1,hash(completed.get(i)),fit.iterations(),fit.converged(),fit.locallyIdentified()));if(progress!=null)progress.accept(completed.size()+i+1);}
        boolean[] testable=new boolean[labels.size()];for(int j=0;j<testable.length;j++)testable[j]=model.parameters().get(j).locations().stream().noneMatch(l->l.kind()==SemModel.Kind.COVARIANCE);var pooled=RubinPooling.pool(estimates,options.analysis().confidence(),options.completeDegreesOfFreedom(),testable);warnings.addAll(pooled.warnings());warnings.add("The report retains imputation hashes/traces and original-source provenance, not all completed datasets. Reproduce them from the original source, declared method and seed. Pooled LL/AIC/BIC/CFI are not obtained by averaging complete-data fit statistics.");return new Fit(model,options,imputed.suppliedRows(),imputed.sourceRows(),imputed.missingCells(),imputed.maximumSplitRhat(),imputed.meanTraces(),pooled,analyses,warnings);
    }
    static String hash(double[][] data){try{var digest=MessageDigest.getInstance("SHA-256");digest.update(ByteBuffer.allocate(8).putInt(data.length).putInt(data.length==0?0:data[0].length).array());ByteBuffer buffer=ByteBuffer.allocate(8);for(var row:data)for(double value:row){buffer.clear();buffer.putLong(Double.doubleToLongBits(value));digest.update(buffer.array());}return java.util.HexFormat.of().formatHex(digest.digest());}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
